(1,'property-setup','Property Setup & Mapping Pro','Multi-property, buildings, wings and floor mapping.',499.00,4990.00,'property','bi-building-gear','active',1,1,'2026-08-26 10:16:52','2026-09-03 13:55:01'),(2,'room_bed_management','Room & Bed Management','Track rooms, sharing tiers, availability, and interactive bed occupant mapping.',499.00,2000.00,'property','bi-door-open','active',1,2,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(3,'resident_management','Resident Management','Manage resident profiles, check-in statuses, and demographics.',499.00,2500.00,'property','bi-people','active',1,3,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(4,'staff_management','Staff Management & RBAC','Invite admins, wardens, billing specialists, kitchen teams, and guards.',299.00,1500.00,'property','bi-person-badge','active',1,4,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(5,'resident_users','Resident User Accounts','Maintain resident login credentials and contact profiles.',199.00,0.00,'property','bi-person-vcard','active',1,5,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(6,'resident_app','Dedicated Resident App','Mobile web application for residents to view dues, meals, and tickets.',499.00,8000.00,'resident','bi-phone','active',1,11,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(7,'resident_login','Resident Password Login','Role-secured encrypted login portal for verified active residents.',149.00,0.00,'resident','bi-key','active',1,12,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(8,'email_otp_login','Email OTP Instant Login','Passwordless verification codes dispatched directly to resident emails.',199.00,0.00,'resident','bi-envelope-check','active',1,13,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(9,'resident_profile','Resident Digital ID Profile','Emergency contacts, room details, and personal profile management.',99.00,0.00,'resident','bi-person-circle','active',1,14,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(10,'resident_documents','KYC & Document Storage','Secure Aadhaar, passport, student ID, and lease verification storage.',249.00,2000.00,'property','bi-file-earmark-check','active',1,6,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(11,'resident_notifications','Resident In-App Notifications','Broadcast property alerts, payment dues, and inspection schedules.',149.00,1500.00,'resident','bi-bell','active',1,15,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(12,'resident_announcements','Digital Notice Board','Broadcast system-wide notices, dining schedules, and emergency alerts.',149.00,1000.00,'resident','bi-megaphone','active',1,16,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(13,'billing_invoices','Automated Invoices & Ledgers','Generate recurring monthly invoices on the 1st of every month automatically.',599.00,5000.00,'billing','bi-receipt','active',1,18,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(14,'payment_collection','Online Payment Collection (UPI)','Direct UPI QR code collection with automated reference tracking.',499.00,3000.00,'billing','bi-qr-code','active',1,19,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(15,'payment_reconciliation','Bank Payment Reconciliation','Reconcile UTR reference numbers and match transactions to invoices.',399.00,6000.00,'billing','bi-check-all','active',1,20,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(16,'payment_receipts','Instant PDF Payment Receipts','Generate and download printable, GST-compliant rent receipts.',199.00,1000.00,'billing','bi-file-earmark-pdf','active',1,21,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(17,'outstanding_dues','Outstanding Dues Tracking','Live ledger summaries of pending rent, electricity, and penalties.',299.00,1500.00,'billing','bi-wallet2','active',1,22,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(18,'expense_management','Property Expense Tracking','Track vendor bills, utility bills, maintenance expenses, and groceries.',349.00,3000.00,'billing','bi-cash-coin','active',1,23,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(19,'financial_reports','Financial Reports & P&L','Export monthly collection summaries, revenue curves, and tax sheets.',499.00,2500.00,'billing','bi-graph-up','active',1,28,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(20,'whatsapp_automation','WhatsApp Automation Engine','Automated WhatsApp payment reminders and invoice PDFs via Meta Cloud API.',699.00,7000.00,'communication','bi-whatsapp','active',1,29,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(21,'email_notifications','Transactional Email Gateway','Automated SMTP email notifications for invoices, OTPs, and receipts.',249.00,1000.00,'communication','bi-envelope','active',1,32,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(22,'sms_notifications','DLT Telecom SMS Alerts','Govt-compliant DLT SMS alerts for urgent operational notices.',399.00,2000.00,'communication','bi-chat-square-text','active',1,33,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(23,'push_notifications','Mobile Web Push Alerts','Browser push notifications delivered directly to resident devices.',199.00,1500.00,'communication','bi-broadcast','active',1,34,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(24,'automated_payment_reminders','Automated Due Reminders','Scheduled multi-channel reminders before and on the payment due date.',299.00,2000.00,'communication','bi-alarm','active',1,30,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(25,'automated_resident_notifications','Automated Event Alerts','Trigger instant alerts for ticket updates, meal cutoffs, and passes.',199.00,2000.00,'communication','bi-chat-left-dots','active',1,31,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(26,'maintenance_requests','Resident Maintenance Ticketing','Allow residents to submit repair requests with photos and priority tags.',349.00,2000.00,'maintenance','bi-tools','active',1,36,'2026-08-26 10:16:52','2026-08-31 23:44:56'),(27,'maintenance_ticket_management','Ticket Queue Management','Filter, categorize, and prioritize work orders across property staff.',249.00,2000.00,'maintenance','bi-list-task','active',1,3