('2', 'John Lacker', 'john-lacker', 'CTO', 'Engineering', 'John leads the engineering and system architecture team at StayFlow.', 'John is a seasoned software architect with over 12 years of experience in distributed cloud infrastructure and SaaS scalable platforms.', 'images/ns-avatar-2.png', 'cto@stayflow.antideploy.app', '+1 (368) 567 89 55', 'https://linkedin.com', 'https://facebook.com', NULL, NULL, 'https://github.com', '', NULL, NULL, '', NULL, NULL, NULL, 'published', '2', '2026-09-17 21:21:26', '2026-09-17 21:21:26', 'John Lacker - CTO | StayFlow', 'Meet John Lacker, Chief Technology Officer at StayFlow.', NULL, NULL, NULL, NULL, NULL, '1', '1')
